<?php
namespace Tests\Feature\Documents;
use App\Domain\Authorization\Enums\GeographicScopeLevel;use App\Domain\Documents\Enums\DocumentStatus;use App\Domain\Documents\Services\AuthorizedDocumentQuery;use App\Models\{District,Document,DocumentCategory,DocumentType,RevenueCircle,State,User,UserGeographicScope};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AuthorizedDocumentQueryTest extends TestCase{use RefreshDatabase;public function test_circle_scope_does_not_return_sibling_circle_document():void{$this->seed();$u=User::factory()->create();$s=State::where('code','AS')->first();$d=District::create(['ulid'=>(string)\Illuminate\Support\Str::ulid(),'state_id'=>$s->id,'code'=>'D1','name_en'=>'District']);$c1=RevenueCircle::create(['ulid'=>(string)\Illuminate\Support\Str::ulid(),'district_id'=>$d->id,'code'=>'C1','name_en'=>'Circle 1']);$c2=RevenueCircle::create(['ulid'=>(string)\Illuminate\Support\Str::ulid(),'district_id'=>$d->id,'code'=>'C2','name_en'=>'Circle 2']);UserGeographicScope::create(['user_id'=>$u->id,'scope_level'=>GeographicScopeLevel::RevenueCircle,'revenue_circle_id'=>$c1->id,'assigned_at'=>now()]);$cat=DocumentCategory::create(['code'=>'T','name_en'=>'Test']);$type=DocumentType::create(['document_category_id'=>$cat->id,'code'=>'TT','name_en'=>'Test']);foreach([$c1,$c2] as $i=>$c)Document::create(['reference_no'=>'AS-LR-2026-'.str_pad((string)($i+1),10,'0',STR_PAD_LEFT),'document_category_id'=>$cat->id,'document_type_id'=>$type->id,'state_id'=>$s->id,'district_id'=>$d->id,'revenue_circle_id'=>$c->id,'title'=>'Doc','status'=>DocumentStatus::AwaitingUpload,'registered_by'=>$u->id,'registered_at'=>now()]);$ids=app(AuthorizedDocumentQuery::class)->for($u)->pluck('revenue_circle_id')->all();$this->assertSame([$c1->id],$ids);}}
